-- QB Season Builder: the season model's tables, the schema half of the offline
-- fit (issue #76, sub-issue of #72). The data half is 0126, generated by
-- scripts/qb_season_model/build_model.py from the finished ratings (0124) and the
-- real 2006-2025 seasons.
--
-- This is what season generation (issue #77) reads to turn the six picked values
-- into a season. Nothing here is served to a client: like the ratings it sits in
-- qb_season_builder_private, which is not an exposed schema and grants no usage to
-- anon or authenticated (0120), with the revokes and RLS below as a second lock.
-- A client only ever sees a generated season, through the game API.
--
-- HOW THE PIECES ARE MEANT TO BE USED. Everything is per full season
-- (17 games), so a 16-game 2007 and a 17-game 2023 are comparable.
--
--   1. season_model_outputs + _coefficients: each output is a formula of the six
--      values, linear in a link space:
--         z = intercept + sum(coefficient[slot] * value[slot])
--      and the output is the inverse link of z:
--         identity  z, held to [low, high]
--         log       exp(z), held to at most high
--         logit     low + (high - low) / (1 + exp(-z))
--      The formulas extrapolate: six values above anything real give a season
--      above anything real, but the logit and log links stop a rate leaving what
--      a game allows (wins never pass 17).
--      The stat line is derived from the outputs, so it agrees with itself:
--         completions = attempts * comp_pct      pass_yards    = attempts * ypa
--         pass_td     = attempts * td_rate       interceptions = attempts * int_rate
--         rating = (a + b + c + d) / 6 * 100, each of a..d held to [0, 2.375]:
--           a = (comp_pct - 0.3) * 5      b = (ypa - 3) * 0.25
--           c = td_rate * 20              d = 2.375 - int_rate * 25
--      Rounding is the caller's: counts to whole numbers, and the record as wins
--      rounded with losses = 17 - wins.
--   2. season_model_residuals: the real spread around each formula, as a table of
--      quantiles of the residual, in link units, at p = 0, 0.05 .. 1. To add noise
--      to an output, draw u in [0, 1) from the run's seed, interpolate the
--      residual at u, multiply by the output's noise_scale, and add it to z before
--      the inverse link. The table's ends are the real extremes, so the noise is
--      bounded by what really happened. noise_scale is configuration: near 1 for
--      the `team` group (wins), small for `qb_line`, so noise lands mostly on team
--      outcomes and lightly on the quarterback's own stat line.
--         z = intercept + sum(coefficient * value) + noise_scale * residual_at(u)
--   3. season_model_playoff_ladder: five rungs (make the playoffs, reach the
--      divisional round, the conference game, the Super Bowl, win it). The chance
--      of clearing a rung given the previous one is 1 / (1 + exp(-(intercept +
--      slope * wins))). Walk the rungs with the seed until one is missed.
--   4. season_model_metrics + _formulas: the metrics a season is judged on
--      (pass_yards, pass_td, interceptions, rating, rush_yards, rush_td, wins,
--      playoff_depth) with the real mean and spread of each, and every weighted
--      sum built from them. A formula is sum(weight * (metric - mean) / sd), except
--      `awards`, which is sum of points for the awards earned, and `score`, whose
--      terms weight the three components below.
--   5. season_model_awards: for each award, the award score (formula
--      award_<name>) at or above which it is earned, calibrated on the real winners'
--      seasons. An award is earned when
--         award_score + (2u - 1) * noise_scale * spread >= threshold
--      with u in [0, 1) drawn from the run's seed: `spread` is the real winners' own
--      spread and noise_scale the configured share of it, so only a season near the
--      threshold is ever a coin flip. The awards are judged independently.
--      Super Bowl MVP applies only when the team wins the title.
--   6. season_model_distributions: how the 2006-2025 seasons spread on each score
--      component (stat_line, team_success, awards), as a table of quantiles at
--      p = 0, 0.01 .. 1. A generated season's percentile on a component is the
--      share of the table's values strictly below its composite ("better than X% of
--      real seasons"): a tie is not better, so a season with no awards, like most
--      real ones, is better than none of them on that component, and one above the
--      whole table is exactly 1. The score is 100 * sum(w * percentile) / sum(w)
--      over the `score` formula's weights.
--   7. season_model_real_seasons: every real quarterback-season with its six
--      values, the stat line and record that came with it and its awards. The
--      closest real season is the row nearest the build on the six values.
--      The six values here are copied from qb_seasons/team_seasons when this was
--      generated, and stay in step because a ratings retune is followed by a new
--      fit (the database test checks they agree).

-- ------------------------------------------------------------------- outputs --

create table qb_season_builder_private.season_model_outputs (
  output      text primary key check (output in (
    'attempts', 'comp_pct', 'ypa', 'td_rate', 'int_rate', 'rush_yards', 'rush_td', 'wins'
  )),
  link        text not null check (link in ('identity', 'log', 'logit')),
  low         double precision not null,
  high        double precision not null,
  intercept   double precision not null,
  -- The regression's standard error in link units, and how much of the real spread
  -- the formula explains. For reference: noise is drawn from season_model_residuals.
  residual_sd double precision not null check (residual_sd >= 0),
  r_squared   double precision not null check (r_squared <= 1),
  noise_scale double precision not null check (noise_scale >= 0),
  noise_group text not null check (noise_group in ('team', 'qb_line')),
  check (low < high)
);

create table qb_season_builder_private.season_model_coefficients (
  output      text not null references qb_season_builder_private.season_model_outputs (output)
                on delete cascade,
  slot        text not null check (slot in (
    'accuracy', 'arm_talent', 'mobility', 'iq', 'build', 'supporting_cast'
  )),
  coefficient double precision not null,
  primary key (output, slot)
);

create table qb_season_builder_private.season_model_residuals (
  output   text not null references qb_season_builder_private.season_model_outputs (output)
             on delete cascade,
  p        double precision not null check (p between 0 and 1),
  residual double precision not null,
  primary key (output, p)
);

-- -------------------------------------------------------------------- ladder --

create table qb_season_builder_private.season_model_playoff_ladder (
  rung      smallint primary key check (rung between 1 and 5),
  step      text not null unique check (step in (
    'make_playoffs', 'reach_divisional', 'reach_conference', 'reach_super_bowl', 'win_super_bowl'
  )),
  intercept double precision not null,
  -- More wins is never a worse chance.
  slope     double precision not null check (slope >= 0)
);

-- ------------------------------------------------------ metrics and formulas --

create table qb_season_builder_private.season_model_metrics (
  metric text primary key check (metric in (
    'pass_yards', 'pass_td', 'interceptions', 'rating', 'rush_yards', 'rush_td',
    'wins', 'playoff_depth'
  )),
  mean   double precision not null,
  sd     double precision not null check (sd > 0)
);

create table qb_season_builder_private.season_model_formulas (
  formula text not null check (formula in (
    'score', 'stat_line', 'team_success', 'awards',
    'award_mvp', 'award_opoy', 'award_all_pro', 'award_pro_bowl', 'award_sb_mvp'
  )),
  -- A metric, an award (for `awards`) or a score component (for `score`).
  term    text not null,
  weight  double precision not null,
  primary key (formula, term)
);

create table qb_season_builder_private.season_model_awards (
  award       text primary key check (award in ('mvp', 'opoy', 'all_pro', 'pro_bowl', 'sb_mvp')),
  threshold   double precision not null,
  spread      double precision not null check (spread >= 0),
  noise_scale double precision not null check (noise_scale >= 0),
  -- How many real seasons the threshold was calibrated on.
  winners     integer not null check (winners >= 1)
);

create table qb_season_builder_private.season_model_distributions (
  component text not null check (component in ('stat_line', 'team_success', 'awards')),
  p         double precision not null check (p between 0 and 1),
  value     double precision not null,
  primary key (component, p)
);

-- --------------------------------------------------------------- real seasons --

create table qb_season_builder_private.season_model_real_seasons (
  franchise_code  text     not null,
  season          smallint not null check (season between 2006 and 2025),
  player_id       text     not null,
  display_name    text     not null,
  accuracy        smallint not null check (accuracy between 0 and 99),
  arm_talent      smallint not null check (arm_talent between 0 and 99),
  mobility        smallint not null check (mobility between 0 and 99),
  iq              smallint not null check (iq between 0 and 99),
  build           smallint not null check (build between 0 and 99),
  supporting_cast smallint not null check (supporting_cast between 0 and 99),
  -- What he really did that regular season (not scaled to 17 games).
  attempts        smallint not null check (attempts > 0),
  completions     smallint not null check (completions >= 0),
  pass_yards      integer  not null,
  pass_tds        smallint not null check (pass_tds >= 0),
  interceptions   smallint not null check (interceptions >= 0),
  rush_yards      integer  not null,
  rush_tds        smallint not null check (rush_tds >= 0),
  -- His team's regular-season record, and how far it went: 0 missed the playoffs,
  -- 1 lost the wild card round .. 4 lost the Super Bowl, 5 won it.
  wins            smallint not null check (wins >= 0),
  losses          smallint not null check (losses >= 0),
  ties            smallint not null check (ties >= 0),
  playoff_depth   smallint not null check (playoff_depth between 0 and 5),
  mvp             boolean  not null,
  opoy            boolean  not null,
  all_pro         boolean  not null,
  pro_bowl        boolean  not null,
  sb_mvp          boolean  not null,

  primary key (franchise_code, season, player_id)
);

-- ---------------------------------------------------------------- privileges --

do $$
declare
  v_table text;
begin
  foreach v_table in array array[
    'season_model_outputs', 'season_model_coefficients', 'season_model_residuals',
    'season_model_playoff_ladder', 'season_model_metrics', 'season_model_formulas',
    'season_model_awards', 'season_model_distributions', 'season_model_real_seasons'
  ] loop
    execute format('alter table qb_season_builder_private.%I enable row level security', v_table);
    execute format(
      'revoke all on table qb_season_builder_private.%I from public, anon, authenticated', v_table);
  end loop;
end $$;
